#!/usr/bin/env python3
"""A sourced series page; keep photography bytes intact and avoid inferred artwork facts."""
import json,hashlib
from pathlib import Path
from html import escape as e
R=Path(__file__).resolve().parents[1]/'classic'
BASE='https://naroa.online'; URL=BASE+'/series/vaivenes/'
data=json.loads((R/'data/vaivenes.json').read_text())
SOURCES=data['sources']; images=data['images']
for im in images:
    assert hashlib.sha256((R/im['src'].lstrip('/')).read_bytes()).hexdigest()==im['sha256'],im['src']
def figure(im,n):
 stage='<p class="series-stage">Dibujo del retrato</p>' if im.get("stage")=="dibujo" else ""
 return f'''<figure class="series-work" id="{im['slug']}"><a class="project-photo" href="{im['src']}" data-image="{im['src']}" data-caption="{e(im['title']+' — '+im['caption'])}" aria-label="Ampliar {e(im['title'])}"><img src="{im['src']}" width="{im['width']}" height="{im['height']}" alt="{e(im['title']+' · '+im['caption'])}" loading="{'eager' if n==0 else 'lazy'}" decoding="async"{' fetchpriority="high"' if n==0 else ''}><span aria-hidden="true">Ampliar ↗</span></a><figcaption><span>{n+1:02d}</span><div>{stage}<h2>{e(im['title'])}</h2><p>{e(im['caption'])}</p>{f'<a href="{im["link"]}">Ver la obra y sus detalles →</a>' if im.get('link') else ''}<a class="series-source" href="{e(im['source'])}" target="_blank" rel="noopener noreferrer">Publicación de referencia ↗</a></div></figcaption></figure>'''
series_index=''.join(f'<a href="#{im["slug"]}">{e(im["title"])}</a>' for im in images)
intro=f'''<header class="series-intro"><p class="eyebrow">Una serie de Naroa Gutiérrez Gil</p><h1>Vaivenes</h1><p class="series-lead">Rostros conocidos. Emociones propias.</p><p class="series-description">Iconos de la música, el cine, la literatura y la televisión dan forma a experiencias personales.</p><div class="series-reading"><details class="series-disclosure"><summary>Sobre la serie</summary><div class="series-context"><p>La pintura y el dibujo se encuentran con el collage, los objetos y los materiales reutilizados.</p><p>La serie convierte las idas y venidas de la vida en composiciones con capas, texturas y volumen. Cada rostro abre una manera de mirar lo que ocurre por dentro.</p></div></details><details class="series-disclosure"><summary>Las ocho obras</summary><nav class="series-index" aria-label="Obras de Vaivenes">{series_index}</nav></details></div></header>'''
trail='''<section class="series-trail" aria-labelledby="series-history"><p class="eyebrow">La serie, de sala en sala</p><h2 id="series-history">Un recorrido que continúa.</h2><ol><li><span>2019 · Bilbao</span><a href="SOURCE0">Vaivenes en Copper Deli Museo ↗</a></li><li><span>2020 · Sodupe</span><a href="SOURCE1">Vaivenes en Haika ↗</a></li><li><span>2022 · Bilbao</span><a href="SOURCE2">Repóker de Reinas en Siarte ↗</a></li><li><span>2026 · Bilbao</span><a href="SOURCE3">DiviNos VaiVenes en Politena ↗</a></li></ol><p>Esta selección reúne imágenes de distintas etapas del recorrido. En 2026, Naroa pone en diálogo Vaivenes con los retratos sobre pizarra de DiviNos.</p><a href="/trayectoria/">Ver la trayectoria de Naroa →</a></section>'''
for i,s in enumerate(SOURCES):trail=trail.replace('SOURCE'+str(i),s['url'])
structured={'@context':'https://schema.org','@type':'CollectionPage','name':'Vaivenes · Naroa Gutiérrez Gil','url':URL,'description':'Una selección del recorrido de Vaivenes: retratos, collage y materiales reutilizados para dar forma a emociones propias.','image':[BASE+im['src'] for im in images],'about':{'@type':'CreativeWorkSeries','name':'Vaivenes','creator':{'@type':'Person','name':'Naroa Gutiérrez Gil','url':BASE+'/'}}}
head=f'''<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vaivenes · Retratos y collage | Naroa Gutiérrez Gil</title><meta name="description" content="Descubre Vaivenes de Naroa Gutiérrez Gil: retratos, collage, texturas y materiales reutilizados. Una selección de ocho obras y sus procesos."><meta name="robots" content="index, follow, max-image-preview:large"><link rel="canonical" href="{URL}"><meta property="og:title" content="Vaivenes · Naroa Gutiérrez Gil"><meta property="og:description" content="Rostros conocidos. Emociones propias. Un recorrido por el collage y la materia."><meta property="og:type" content="website"><meta property="og:url" content="{URL}"><meta property="og:image" content="{BASE+images[0]['src']}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon-Inu7iesc.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;700&family=Inter:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/catalogo.css?v=20261021-vaivenes"><link rel="stylesheet" href="/assets/vaivenes.css?v=20261021-inmersivo"><link rel="stylesheet" href="/assets/art-viewer.css?v=20261021-inmersivo"><script defer src="/assets/catalogo.js?v=20261021-inmersivo"></script><script type="application/ld+json">{json.dumps(structured,ensure_ascii=False).replace('<','&lt;')}</script>'''
page=f'''<!doctype html><html lang="es"><head>{head}</head><body class="project-page series-page"><a class="catalog-skip" href="#series-main">Ir al contenido</a><nav class="project-nav" aria-label="Principal"><a class="project-brand" href="/">NAROA<span>Gutiérrez Gil</span></a><a href="/#/destacada">← Volver a la obra</a><a href="/trayectoria/">Trayectoria ↗</a></nav><main id="series-main">{figure(images[0],0)}{intro}{''.join(figure(im,n) for n,im in enumerate(images) if n>0)}{trail}<section class="series-invitation"><p class="eyebrow">Una historia propia</p><h2>¿Qué te gustaría retratar?</h2><a class="editorial-button" href="mailto:naroa@naroa.eu?subject=Consulta%20sobre%20Vaivenes">Cuéntame tu idea ↗</a><a href="/retratos-por-encargo-bilbao/">Retratos por encargo →</a></section></main><footer class="project-footer"><a href="/">Naroa Gutiérrez Gil</a><a href="/sobre-mi/">Sobre mí</a><a href="mailto:naroa@naroa.eu">naroa@naroa.eu ↗</a></footer><dialog id="art-viewer" aria-label="Imagen ampliada"><div class="viewer-bar"><span id="viewer-counter" role="status"></span><button type="button" id="viewer-close">Cerrar ×</button></div><div class="viewer-stage"><button type="button" id="viewer-prev" aria-label="Imagen anterior">←</button><img id="viewer-image" alt=""><button type="button" id="viewer-next" aria-label="Imagen siguiente">→</button></div><p id="viewer-caption" aria-live="polite"></p></dialog></body></html>'''
out=R/'series/vaivenes';out.mkdir(parents=True,exist_ok=True);(out/'index.html').write_text(page)

print(f'Built Vaivenes: {len(images)} documented works and {len(SOURCES)} sources.')
